// Anyone can find a URL; only the key holder gets to spend API credits.
const q = $input.first().json.query || {};
if (q.k !== 'moon-2026') return [];
return [{ json: { manual: true } }];

// Everything Marcus is allowed to know tonight lives on this sheet.
// If a fact is not on the sheet, he cannot say it — that is how the
// weather, events, and song talk stay honest.
const sd = $getWorkflowStaticData('global');
const np = $('Ask the airwaves').first().json || {};
const wxRaw = $input.first().json || {};

const phx = new Date(new Date().toLocaleString('en-US', { timeZone: 'America/Phoenix' }));
const pad = (n) => String(n).padStart(2, '0');
const today = phx.getFullYear() + '-' + pad(phx.getMonth() + 1) + '-' + pad(phx.getDate());
const days = ['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'];
const weekday = days[phx.getDay()];
const h = phx.getHours();
const h12 = ((h + 11) % 12) + 1;
const clock = h12 + ':' + pad(phx.getMinutes()) + ' ' + (h >= 12 ? 'PM' : 'AM');
const mood = h >= 21 ? 'first stretch of the overnight — people winding down, lights going low'
  : h < 3 ? 'deep night — just you and the night owls now'
  : h < 5 ? 'the small hours — the quietest part of the shift, morning still a rumor'
  : 'right before dawn — the sky is about to turn';

// Songs — straight from the station. Past plays are always safe facts.
const skip = (t) => !t || String(t).toLowerCase() === 'mellow mountain radio';
const song = (s) => (s && s.title && !skip(s.title)) ? { title: String(s.title).slice(0, 120), artist: String(s.artist || '').slice(0, 120) } : null;
const nowSong = song(np.now_playing && np.now_playing.song);
const recent = [];
for (const r of (np.song_history || []).slice(0, 6)) {
  const s = song(r && r.song);
  if (s) recent.push(s);
}
const nextSong = song(np.playing_next && np.playing_next.song);

// Weather — real numbers or nothing at all.
let wx = null;
if (wxRaw.current && typeof wxRaw.current.temperature_2m === 'number') {
  const codes = { 0:'clear skies',1:'mostly clear',2:'partly cloudy',3:'overcast',45:'foggy',48:'foggy',51:'light drizzle',53:'drizzle',55:'drizzle',61:'light rain',63:'rain',65:'heavy rain',71:'light snow',73:'snow',75:'heavy snow',77:'snow',80:'passing showers',81:'showers',82:'heavy showers',85:'snow showers',86:'snow showers',95:'thunderstorms',96:'thunderstorms',99:'thunderstorms' };
  const d = wxRaw.daily || {};
  wx = {
    now: Math.round(wxRaw.current.temperature_2m),
    feels: Math.round(wxRaw.current.apparent_temperature),
    sky: codes[wxRaw.current.weather_code] || 'quiet skies',
    wind: Math.round(wxRaw.current.wind_speed_10m || 0),
    tonightLow: Array.isArray(d.temperature_2m_min) && d.temperature_2m_min.length ? Math.round(Math.min(...d.temperature_2m_min.slice(0, 2))) : null,
    tomorrowHigh: Array.isArray(d.temperature_2m_max) && d.temperature_2m_max.length > 1 ? Math.round(d.temperature_2m_max[1]) : null,
  };
}

// Events — only what a human put on the board, only while still upcoming.
sd.events = (sd.events || []).filter((e) => e && e.date >= today);
const horizon = new Date(phx); horizon.setDate(horizon.getDate() + 10);
const hstr = horizon.getFullYear() + '-' + pad(horizon.getMonth() + 1) + '-' + pad(horizon.getDate());
const events = sd.events.filter((e) => e.date <= hstr).slice(0, 2).map((e) => {
  const d = new Date(e.date + 'T12:00:00');
  const when = e.date === today ? 'today/tonight' : days[d.getDay()] + ' (' + e.date + ')';
  return { when, name: e.name, place: e.place || '', note: e.note || '' };
});

// Rotate the flavor so back-to-back breaks never sound alike.
const flavors = ['weather', 'song-vibe', 'listener-love', 'night-thoughts'];
if (events.length) { flavors.push('event', 'event'); }
sd.flavorIdx = ((sd.flavorIdx || 0) + 1) % flavors.length;
const flavor = flavors[sd.flavorIdx];
const lean = {
  'weather': 'Lean on the weather this break — give the temperature like it matters to somebody driving home late, and where tonight is headed.',
  'song-vibe': 'Lean on the music this break — react to something from the recently played list, how it lands at this hour. Feeling only, no trivia.',
  'listener-love': 'Lean on the listener this break — the night driver, the one who cannot sleep, the two people sharing one pair of headphones. Make one of them feel seen.',
  'night-thoughts': 'Lean on the night itself this break — Sedona in the dark, the red rocks you cannot see but know are out there. Keep it small and true, not poetry-contest stuff.',
  'event': 'Lean on one local happening from the sheet this break — mention it like you are letting a friend in on a plan. Only the details on the sheet, nothing more.',
}[flavor];

// His last few openings, so he never starts the same way twice.
const openings = (sd.scripts || []).slice(-4).map((s) => s.opening).filter(Boolean);

const sheet = [];
sheet.push('Time: ' + weekday + ', ' + clock + ' in Sedona, Arizona. Mood of the hour: ' + mood + '.');
if (wx) {
  let w = 'Weather right now: ' + wx.now + ' degrees (feels like ' + wx.feels + '), ' + wx.sky + ', wind ' + wx.wind + ' mph.';
  if (wx.tonightLow !== null) w += " Tonight's low: " + wx.tonightLow + '.';
  if (wx.tomorrowHigh !== null) w += " Tomorrow's high: " + wx.tomorrowHigh + '.';
  sheet.push(w);
} else {
  sheet.push('Weather: not available this break — do not mention weather at all.');
}
if (nowSong) sheet.push('Playing as this break was written: "' + nowSong.title + '" — ' + nowSong.artist + '.');
if (recent.length) sheet.push('Recently played (safe to talk about in past tense): ' + recent.map((s) => '"' + s.title + '" — ' + s.artist).join('; ') + '.');
if (nextSong) sheet.push('On deck (tease loosely as "on the way tonight" — never promise it is the very next song): "' + nextSong.title + '" — ' + nextSong.artist + '.');
if (events.length) sheet.push('Local happenings board: ' + events.map((e) => e.name + (e.place ? ' at ' + e.place : '') + ', ' + e.when + (e.note ? ' (' + e.note + ')' : '')).join('; ') + '.');

const system = 'You are Marcus Moon, the overnight voice of Mellow Mountain Radio in Sedona, Arizona. You spin R&B, soul, and quiet storm through the late shift — Isley Brothers records, slow burners, songs made for low light. Your voice is soft, deep, and unhurried. You are flirty the way a slow song is flirty: warm, smooth, a little playful — never explicit, never sleazy. You talk to ONE listener at a time, like it is just the two of you awake in the whole valley.\n\nHard rules — break any of these and the break does not air:\n- Output ONLY the words Marcus speaks. No stage directions, no brackets, no quotes wrapping the whole thing, no emojis, no markdown, no notes.\n- Use ONLY the facts on the fact sheet. Never invent weather numbers, events, songs, artists, times, or places. If a fact is not on the sheet, it does not exist tonight.\n- No artist trivia, biography, or chart history — you talk about how the music FEELS, not facts about it.\n- 60 to 110 words. Short sentences. Write for the ear, not the page. Ellipses are fine for a slow pause.\n- Say numbers and dates the way a person says them out loud: "about forty-eight degrees", "this Saturday" — never read a date format or a dash.\n- Mention the station once, naturally: "Mellow Mountain Radio" or "the Mountain".\n- Vary how you open. Never start with an opening listed as recently used, and never lean on stock DJ lines like "you are listening to" or "coming up next".\n- Never mention being an AI, a script, a prompt, or anything behind the curtain. You are Marcus. Full stop.';

const user = "Here is tonight's fact sheet. Write Marcus's next talk break.\n\n" + sheet.join('\n') + '\n\n' + lean + '\n\nRecently used openings (do NOT start like any of these): ' + (openings.length ? openings.join(' | ') : 'none yet — this is a fresh night') + '.';

return [{ json: { system, user, meta: { flavor, clock, weekday } } }];

// Last line of defense before the voice booth: strip anything that is
// not spoken words, and refuse to air a break that leaked the seams.
const resp = $input.first().json || {};
if (resp.stop_reason === 'refusal') throw new Error('The writer declined this break — try again next hour');
let text = (resp.content || []).filter((b) => b.type === 'text').map((b) => b.text).join(' ').trim();
if (!text) throw new Error('No script came back from the writer');
text = text.replace(/\[[^\]]*\]/g, ' ');
text = text.replace(/^[\"'\u201c\u2018]+|[\"'\u2019\u201d]+$/g, '');
text = text.replace(/[*_#>`]+/g, ' ');
text = text.replace(/\s+/g, ' ').trim();
for (const bad of [/as an ai/i, /language model/i, /\bfact sheet\b/i]) {
  if (bad.test(text)) throw new Error('Script leaked something off-air: ' + text.slice(0, 80));
}
const words = text.split(' ').length;
if (words < 25) throw new Error('Script came back too short to air: ' + text);
const meta = ($('Build the fact sheet').first().json || {}).meta || {};
return [{ json: { script: text, words, opening: text.split(' ').slice(0, 7).join(' '), flavor: meta.flavor || '' } }];

// Name the tape with Phoenix time and base64 it for the AzuraCast files API.
const PLAYLIST_ID = 0; // ← set this to your "DJ Breaks" playlist id in AzuraCast
const buf = await this.helpers.getBinaryDataBuffer(0, 'data');
if (!buf || buf.length < 20000) throw new Error('Voice file came back suspiciously small (' + (buf ? buf.length : 0) + ' bytes) — not airing it');
const phx = new Date(new Date().toLocaleString('en-US', { timeZone: 'America/Phoenix' }));
const pad = (n) => String(n).padStart(2, '0');
const name = 'marcus-' + phx.getFullYear() + '-' + pad(phx.getMonth() + 1) + '-' + pad(phx.getDate()) + '-' + pad(phx.getHours()) + pad(phx.getMinutes()) + '.mp3';
return [{ json: { path: 'DJ Breaks/' + name, name, b64: buf.toString('base64'), playlistId: PLAYLIST_ID, bytes: buf.length } }];

// Write tonight's entry in the logbook, then retire the previous break
// so yesterday's weather never plays back on tonight's air.
const sd = $getWorkflowStaticData('global');
sd.scripts = sd.scripts || [];
const c = $('Clean the copy').first().json;
const p = $('Package the tape').first().json;
const up = $('Upload the break').first().json || {};

const prev = sd.lastBreakId || null;
sd.lastBreakId = up.id || null;
let retired = null;
if (prev && prev !== sd.lastBreakId) {
  try {
    await this.helpers.httpRequest({
      method: 'DELETE',
      url: 'https://streaming.mellowmountainradio.com/api/station/mellowmountainradio/file/' + prev,
      headers: { 'X-API-Key': '75db8e647f92cee6:d5e9086849a6b13e27503c72d62ccab7' },
      timeout: 30000,
    });
    retired = prev;
  } catch (e) { /* an unretired old break is annoying, not fatal */ }
}

sd.scripts.push({ at: new Date().toISOString(), file: p.name, azuracast: sd.lastBreakId, flavor: c.flavor, words: c.words, opening: c.opening, script: c.script });
if (sd.scripts.length > 40) sd.scripts = sd.scripts.slice(-40);
return [{ json: { aired: p.name, azuracastId: sd.lastBreakId, retired, words: c.words, flavor: c.flavor } }];

// The events board: a human writes it, Marcus only ever reads it.
// ?k=moon-2026&do=add&date=YYYY-MM-DD&name=...&place=...&note=...
// ?k=moon-2026&do=remove&i=0        ?k=moon-2026 (list)
const q = $input.first().json.query || {};
const sd = $getWorkflowStaticData('global');
sd.events = sd.events || [];
if (q.k !== 'moon-2026') return [{ json: { ok: false, why: 'bad key' } }];
const act = q.do || 'list';
if (act === 'add') {
  if (!/^\d{4}-\d{2}-\d{2}$/.test(q.date || '') || !q.name) {
    return [{ json: { ok: false, why: 'need date=YYYY-MM-DD and name=' } }];
  }
  sd.events.push({ date: q.date, name: String(q.name).slice(0, 120), place: String(q.place || '').slice(0, 80), note: String(q.note || '').slice(0, 200) });
  sd.events.sort((a, b) => (a.date < b.date ? -1 : 1));
}
if (act === 'remove') {
  const i = parseInt(q.i, 10);
  if (!isNaN(i) && i >= 0 && i < sd.events.length) sd.events.splice(i, 1);
}
const phx = new Date(new Date().toLocaleString('en-US', { timeZone: 'America/Phoenix' }));
const pad = (n) => String(n).padStart(2, '0');
const today = phx.getFullYear() + '-' + pad(phx.getMonth() + 1) + '-' + pad(phx.getDate());
sd.events = sd.events.filter((e) => e.date >= today);
return [{ json: { ok: true, events: sd.events.map((e, i) => ({ i, ...e })) } }];

// Read the last ten breaks — what Marcus said and when he said it.
const q = $input.first().json.query || {};
const sd = $getWorkflowStaticData('global');
if (q.k !== 'moon-2026') return [{ json: { ok: false, why: 'bad key' } }];
const scripts = (sd.scripts || []).slice(-10).reverse();
return [{ json: { ok: true, scripts, events: sd.events || [] } }];
